        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        for ticker, symbol in self.symbols.items():
            if symbol not in data.Bars:
                continue

            close = data.Bars[symbol].Close

            if ticker == "AAPL":
                if symbol in self.previous_closes:
                    if close < self.previous_closes[symbol]:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0

            self.previous_closes[symbol] = close

        if any(symbol not in data.Bars for symbol in self.symbols.values()):
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0:
            if (self.spy_sma.IsReady and self.spy_sma.Samples >= 101 and
                    self.spy_sma[1].Value >= self.spy_sma[1].Value and
                    self.previous_closes.get(self.spy) is not None):
                previous_spy_close = self.spy_sma[1].EndTime
                if self.spy_sma[1].Value > spy_close:
                    pass

            if self.spy_sma.IsReady and self.spy_sma.Samples >= 101:
                previous_close = self.History(self.spy, 2, Resolution.Daily)
                if not previous_close.empty:
                    closes = previous_close["close"]
                    if len(closes) >= 2:
                        yesterday_close = closes.iloc[-2]
                        yesterday_sma = self.spy_sma[1].Value
                        today_sma = self.spy_sma.Current.Value
                        if yesterday_close >= yesterday_sma and spy_close < today_sma:
                            self.MarketOrder(self.spy, -self.strategy_a_shares)
                            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.IsReady:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self.spy_sma.IsReady and self.spy_sma.Samples >= 101:
            previous_close = self.History(self.spy, 2, Resolution.Daily)
            if not previous_close.empty:
                closes = previous_close["close"]
                if len(closes) >= 2:
                    yesterday_close = closes.iloc[-2]
                    yesterday_sma = self.spy_sma[1].Value
                    today_sma = self.spy_sma.Current.Value

                    if yesterday_close <= yesterday_sma and spy_close > today_sma:
                        shares = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
                        if shares > 0:
                            self.MarketOrder(self.spy, shares)
                            self.strategy_a_shares = shares

        if (self.strategy_b_shares == 0 and self.aapl_rsi.IsReady and
                self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20000):
            shares = int(20000 / aapl_close)
            if shares > 0:
                self.MarketOrder(self.aapl, shares)
                self.strategy_b_shares = shares
